#include <cmath>
#include <limits>

struct Model {
    struct Node {
        double x = 0.f;
        double y = 0.f;
    };

    struct Road {
        enum Type { Invalid, Unclassified, Service, Residential, Tertiary, Secondary, Primary, Trunk, Motorway, Footway };
        int way;
        Type type;
    };

    std::vector<Node> m_Nodes;
    std::vector<Road> m_Roads;
};

class RouteModel : public Model {
public:
    class Node : public Model::Node {
    public:
        Node* parent = nullptr;
        float h_value = std::numeric_limits<float>::max();
        float g_value = 0.0;
        bool visited = false;
        std::vector<Node*> neighbors;

        Node() = default;
        Node(int idx, RouteModel* search_model, Model::Node node) : Model::Node(node) {}
    };

    std::vector<Node> m_nodes;

    Node& find_closest_node(float x, float y) {
        Node* closest_node = nullptr;
        float min_distance = std::numeric_limits<float>::max();

        for (auto& node : m_nodes) {
            float distance = std::sqrt(std::pow(x - node.x, 2) + std::pow(y - node.y, 2));
            if (distance < min_distance) {
                min_distance = distance;
                closest_node = &node;
            }
        }

        return *closest_node;
    }
};

int main() {
    RouteModel model;
    RouteModel::Node node1;
    node1.x = 0.0;
    node1.y = 0.0;
    model.m_nodes.push_back(node1);

    RouteModel::Node node2;
    node2.x = 1.0;
    node2.y = 1.0;
    model.m_nodes.push_back(node2);

    auto& result = model.find_closest_node(0.1f, 0.1f);
    return 0;
}

